USE CakesDB; GO   -- 1. SELECT з однієї таблиці + OR + ORDER BY SELECT * FROM Clients WHERE address = 'Львів' OR address = 'Київ' ORDER BY surname;   -- 2. SELECT з обчислюваним полем SELECT name, weight, weight * 250 AS estimated_price FROM Cakes;   -- 3. SELECT з кількох таблиць + AND/OR + ORDER BY SELECT c.firstname, o.order_number, o.status FROM Clients c JOIN Orders o ON c.id = o.client_id WHERE o.status = 'done' OR o.status = 'in_progress' ORDER BY o.order_date;   -- 4. OUTER JOIN SELECT c.firstname, o.order_number FROM Clients c LEFT JOIN Orders o ON c.id = o.client_id;   -- 5. LIKE + BETWEEN + IN SELECT * FROM Clients WHERE surname LIKE 'І%' AND id BETWEEN 1 AND 5 AND address IN ('Львів', 'Київ');  -- 6. EXISTS SELECT firstname FROM Clients c WHERE EXISTS (  SELECT 1     FROM Orders o     WHERE o.client_id = c.id );   -- 7. ALL SELECT * FROM Orders WHERE total_cost > ALL (     SELECT total_cost     FROM Orders     WHERE status = 'in_progress' );   -- 8. ANY SELECT * FROM Orders WHERE total_cost > ANY (     SELECT total_cost     FROM Orders     WHERE status = 'done' );   -- 9. GROUP BY + SUM SELECT order_id, SUM(amount) AS total_paid FROM Payments GROUP BY order_id;   -- 10. Підзапит у WHERE SELECT * FROM Orders WHERE total_cost > (     SELECT AVG(total_cost)     FROM Orders );   -- 11. Підзапит у FROM SELECT avg_table.avg_cost FROM (     SELECT AVG(total_cost) AS avg_cost     FROM Orders ) AS avg_table;   -- 12. Ієрархічний SELECT SELECT o.id, c.firstname, p.fullname FROM Orders o JOIN Clients c ON o.client_id = c.id JOIN PastryChefs p ON o.chef_id = p.id;   -- 13. CrossTab (PIVOT) SELECT * FROM (     SELECT status, total_cost     FROM Orders ) AS source_table PIVOT (     SUM(total_cost)     FOR status IN ([new], [in_progress], [done]) ) AS pivot_table;   -- 14. UPDATE однієї таблиці UPDATE Orders SET status = 'in_progress' WHERE id = 1;   -- 15. UPDATE кількох таблиць UPDATE o SET o.total_cost = o.total_cost * 1.1 FROM Orders o JOIN Clients c ON o.client_id = c.id WHERE c.address = 'Львів';   -- 16. INSERT з явними значеннями INSERT INTO Clients (surname, firstname, phone, email, address) VALUES ('Коваль', 'Марія', '111111111', 'newclient@gmail.com', 'Рівне');   -- 17. INSERT з іншої таблиці INSERT INTO Payments (payment_number, payment_type, amount, order_id) SELECT      o.id + 200,     p.payment_type,     o.total_cost,     o.id FROM Orders o JOIN Payments p ON o.id = p.order_id;  -- 18. DELETE вибраних записів DELETE FROM Clients WHERE address = 'Рівне';   -- 19. DELETE всіх даних з таблиці DELETE FROM Payments;   -- 20. Складні запити  SELECT c.firstname,        COUNT(o.id) AS orders_count,        SUM(o.total_cost) AS total_spent FROM Clients c JOIN Orders o ON c.id = o.client_id GROUP BY c.firstname HAVING SUM(o.total_cost) > 1000;   SELECT c.firstname, o.order_number, o.total_cost FROM Clients c JOIN Orders o ON c.id = o.client_id WHERE o.total_cost > (     SELECT AVG(total_cost)     FROM Orders ) ORDER BY o.total_cost DESC;  